/** Each definition: its base type, the parts of a list or an object, and the names of its own rules. */
export const Definitions = {
  customer_id: { base: "string", rules: ["pattern"] },
  name: { base: "string", rules: ["minLength"] },
  customer: { base: "object", properties: ["customer_id","name"], rules: ["required"] },
  peril: { base: "string", rules: ["enum"] },
  limit: { base: "integer", rules: ["exclusiveMinimum"] },
  remark: { base: "string", rules: ["maxLength"] },
  coverage: { base: "object", properties: ["peril","limit","remark"], rules: ["required"] },
  coverages: { base: "array", items: "coverage", rules: ["minItems","maxItems","one_coverage_per_peril"] },
  policy_id: { base: "string", rules: ["pattern"] },
  holder: { base: "string", rules: [] },
  effective_at: { base: "string", rules: ["format"] },
  expires_at: { base: "string", rules: ["format"] },
  premium: { base: "integer", rules: ["exclusiveMinimum"] },
  deductible: { base: "integer", rules: ["minimum"] },
  policy: { base: "object", properties: ["policy_id","holder","coverages","effective_at","expires_at","premium","deductible"], rules: ["required","term_is_positive","term_at_most_a_year","deductible_below_premium"] },
  policy_issued: { base: "object", properties: ["policy_id","holder","premium"], rules: ["required"] },
  issued: { base: "object", properties: ["policy","policy_issued"], rules: ["required"] },
  stored_policy: { base: "object", properties: ["policy_id","holder","coverages","effective_at","expires_at","premium","deductible"], rules: [] },
  cancelled_at: { base: "string", rules: ["format"] },
  cancellation: { base: "object", properties: ["stored_policy","cancelled_at"], rules: ["required","cancellation_within_term"] },
  refund: { base: "integer", rules: ["minimum"] },
  policy_cancelled: { base: "object", properties: ["policy_id","cancelled_at","refund"], rules: ["required"] },
  refund_quote: { base: "object", properties: ["refund","policy_cancelled"], rules: ["required"] },
  refund_refused: { base: "object", properties: ["policy_id","cancelled_at","refund"], rules: ["required"] },
  refund_below_minimum: { base: "object", properties: ["refund","refund_refused"], rules: ["required"] },
} as const;

/** The name of a definition. */
export type DefinitionName = keyof typeof Definitions;

const CHECKS: Readonly<Record<DefinitionName, (value: unknown, path: string, failures: Failure[]) => boolean>> = {
  customer_id: check_customer_id,
  name: check_name,
  customer: check_customer,
  peril: check_peril,
  limit: check_limit,
  remark: check_remark,
  coverage: check_coverage,
  coverages: check_coverages,
  policy_id: check_policy_id,
  holder: check_holder,
  effective_at: check_effective_at,
  expires_at: check_expires_at,
  premium: check_premium,
  deductible: check_deductible,
  policy: check_policy,
  policy_issued: check_policy_issued,
  issued: check_issued,
  stored_policy: check_stored_policy,
  cancelled_at: check_cancelled_at,
  cancellation: check_cancellation,
  refund: check_refund,
  policy_cancelled: check_policy_cancelled,
  refund_quote: check_refund_quote,
  refund_refused: check_refund_refused,
  refund_below_minimum: check_refund_below_minimum,
};

/** The result of a check: the value, or the rules it breaks. */
export type CheckResult<T> = { readonly ok: true; readonly value: T } | { readonly ok: false; readonly failures: readonly Failure[] };

/** The types of the definitions, by name. */
export interface DefinitionTypes {
  readonly customer_id: CustomerId;
  readonly name: Name;
  readonly customer: Customer;
  readonly peril: Peril;
  readonly limit: Limit;
  readonly remark: Remark;
  readonly coverage: Coverage;
  readonly coverages: Coverages;
  readonly policy_id: PolicyId;
  readonly holder: Holder;
  readonly effective_at: EffectiveAt;
  readonly expires_at: ExpiresAt;
  readonly premium: Premium;
  readonly deductible: Deductible;
  readonly policy: Policy;
  readonly policy_issued: PolicyIssued;
  readonly issued: Issued;
  readonly stored_policy: StoredPolicy;
  readonly cancelled_at: CancelledAt;
  readonly cancellation: Cancellation;
  readonly refund: Refund;
  readonly policy_cancelled: PolicyCancelled;
  readonly refund_quote: RefundQuote;
  readonly refund_refused: RefundRefused;
  readonly refund_below_minimum: RefundBelowMinimum;
}

/** Checks a value against a definition: its structure, then each rule. */
export function check<D extends DefinitionName>(definition: D, value: unknown): CheckResult<DefinitionTypes[D]> {
  const failures: Failure[] = [];
  return CHECKS[definition](value, '', failures) ? { ok: true, value: value as DefinitionTypes[D] } : { ok: false, failures };
}

/** What an operation answers: one of its outputs, by name, and its value. */
export interface Answer<O extends string, V> {
  readonly output: O;
  readonly value: V;
}

/** An answer of the core: answer('booking', booking). */
export function answer<O extends string, V>(output: O, value: V): Answer<O, V> {
  return { output, value };
}

/** The answers of issue_policy. */
export type IssuePolicyAnswer = Answer<"issued", Issued>;

/** The answers of cancel_policy. */
export type CancelPolicyAnswer = Answer<"refund_quote", RefundQuote> | Answer<"refund_below_minimum", RefundBelowMinimum>;

/** The core: a function for each operation, from its input to one of its answers. */
export interface DomainCore {
  /** Issue a policy as requested */
  readonly issue_policy: (input: Policy) => IssuePolicyAnswer;
  /** Stop a policy and calculate the refund for the days it does not cover */
  readonly cancel_policy: (input: Cancellation) => CancelPolicyAnswer;
}

/** Each operation: its input, and its outputs. */
export const Operations = {
  issue_policy: { input: "policy", outputs: ["issued"] },
  cancel_policy: { input: "cancellation", outputs: ["refund_quote","refund_below_minimum"] },
} as const;

/** The name of an operation. */
export type OperationName = keyof typeof Operations;

const OPERATION_RULES: Readonly<Record<OperationName, (input: any, output: string, value: any, failures: Failure[]) => boolean>> = {
  issue_policy: (input, output, value, failures) => {
    let ok = true;
    switch (output) {
      case "issued":
        if (!$holds(() => $eq((value as any)["policy"], input))) {
          failures.push({ definition: "issue_policy", rule: "issued_as_requested", path: '', message: "The policy issued is not the one requested" });
          ok = false;
        }
        if (!$holds(() => (($eq(((value as any)["policy_issued"] as any)["policy_id"], (input as any)["policy_id"]) && $eq(((value as any)["policy_issued"] as any)["holder"], (input as any)["holder"])) && $eq(((value as any)["policy_issued"] as any)["premium"], (input as any)["premium"])))) {
          failures.push({ definition: "issue_policy", rule: "announces_the_policy", path: '', message: "The event does not name the policy issued" });
          ok = false;
        }
        break;
    }
    return ok;
  },
  cancel_policy: (input, output, value, failures) => {
    let ok = true;
    switch (output) {
      case "refund_quote":
        if (!$holds(() => (((value as any)["refund"] as any) >= (100 as any)))) {
          failures.push({ definition: "cancel_policy", rule: "refund_at_least_minimum", path: '', message: "A refund below 100 cents is not paid" });
          ok = false;
        }
        if (!$holds(() => (((value as any)["refund"] as any) <= (((input as any)["stored_policy"] as any)["premium"] as any)))) {
          failures.push({ definition: "cancel_policy", rule: "refund_at_most_premium", path: '', message: "The refund is more than the premium" });
          ok = false;
        }
        if (!$holds(() => (($eq(((value as any)["policy_cancelled"] as any)["policy_id"], ((input as any)["stored_policy"] as any)["policy_id"]) && $eq(((value as any)["policy_cancelled"] as any)["cancelled_at"], (input as any)["cancelled_at"])) && $eq(((value as any)["policy_cancelled"] as any)["refund"], (value as any)["refund"])))) {
          failures.push({ definition: "cancel_policy", rule: "announces_the_cancellation", path: '', message: "The event does not name the cancellation" });
          ok = false;
        }
        break;
      case "refund_below_minimum":
        if (!$holds(() => (((value as any)["refund"] as any) < (100 as any)))) {
          failures.push({ definition: "cancel_policy", rule: "refund_under_minimum", path: '', message: "A refund of 100 cents or more is paid" });
          ok = false;
        }
        if (!$holds(() => (((value as any)["refund"] as any) <= (((input as any)["stored_policy"] as any)["premium"] as any)))) {
          failures.push({ definition: "cancel_policy", rule: "refund_at_most_premium", path: '', message: "The refund is more than the premium" });
          ok = false;
        }
        if (!$holds(() => (($eq(((value as any)["refund_refused"] as any)["policy_id"], ((input as any)["stored_policy"] as any)["policy_id"]) && $eq(((value as any)["refund_refused"] as any)["cancelled_at"], (input as any)["cancelled_at"])) && $eq(((value as any)["refund_refused"] as any)["refund"], (value as any)["refund"])))) {
          failures.push({ definition: "cancel_policy", rule: "records_the_refusal", path: '', message: "The event does not record the refusal" });
          ok = false;
        }
        break;
    }
    return ok;
  },
};

/**
 * The result of a call: the answer, or the rules that the input or the answer breaks. InputRejected:
 * the caller sent an input that breaks the contract. ContractViolation: the core answered what the
 * contract does not allow, which is a bug in the core.
 */
export type OperationResult<N extends OperationName = OperationName> =
  | ({ readonly ok: true; readonly operation: N } & ReturnType<DomainCore[N]>)
  | { readonly ok: false; readonly operation: N; readonly kind: 'InputRejected' | 'ContractViolation'; readonly failures: readonly Failure[] };

/** Runs an operation through the harness: checks the input, calls the core, then checks the answer and the rules. */
export function runOperation<N extends OperationName>(core: DomainCore, operation: N, input: unknown): OperationResult<N> {
  const contract = Operations[operation];
  const failures: Failure[] = [];
  if (!CHECKS[contract.input](input, '', failures)) return { ok: false, operation, kind: 'InputRejected', failures };
  const answered: unknown = (core[operation] as (input: unknown) => unknown)(input);
  const outputs: readonly string[] = contract.outputs;
  if (!$isObject(answered) || typeof answered['output'] !== 'string' || !outputs.includes(answered['output'])) {
    const message = `Must answer one of the outputs of ${operation}: ${outputs.join(', ')}`;
    return { ok: false, operation, kind: 'ContractViolation', failures: [{ definition: operation, rule: 'output', path: '', message }] };
  }
  const output = answered['output'] as DefinitionName;
  if (!CHECKS[output](answered['value'], 'output', failures) || !OPERATION_RULES[operation](input, output, answered['value'], failures)) {
    return { ok: false, operation, kind: 'ContractViolation', failures };
  }
  return { ok: true, operation, output, value: answered['value'] } as OperationResult<N>;
}
